/* Auth Pages (Login) Styles    */
/* Auth Body  */
.auth-body {
    margin: 0;
    background: #fff;
    overflow: hidden;
}

/*Split Layout  */
.auth-split {
    display: flex;
    min-height: 100vh;
}

/* LEFT Panel */
.auth-left {
    width: 45%;
    background: #7D1316;
    color: #fff;
    display: flex;
    flex-direction: column;
    padding: 40px;
    position: relative;
    overflow: hidden;
}

.auth-left::before {
    /* Subtle texture overlay */
    content: '';
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse at 30% 20%, rgba(255, 255, 255, 0.04) 0%, transparent 60%);
    pointer-events: none;
}

/* Brand / Logo */
.auth-brand {
    display: flex;
    align-items: center;
    gap: 12px;
}

.auth-logo-box {
    width: 44px;
    height: 44px;
    background: rgba(255, 255, 255, 0.15);
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    flex-shrink: 0;
}

.auth-logo-img {
    width: 150px;
    height: 150px;
    object-fit: contain;
}

.auth-logo-fallback {
    width: 100%;
    height: 100%;
    align-items: center;
    justify-content: center;
}

.auth-brand-name {
    font-size: 1.1rem;
    font-weight: 700;
    letter-spacing: .04em;
    line-height: 1.2;
}

.auth-brand-sub {
    font-size: .65rem;
    letter-spacing: .12em;
    text-transform: uppercase;
    opacity: .7;
    margin-top: 1px;
}

/* Quote area */
.auth-quote-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    justify-content: center;
    padding: 40px 0;
}

.auth-quote-marks {
    font-size: 4rem;
    color: rgba(255, 255, 255, 0.2);
    line-height: 1;
    margin-bottom: -10px;
    font-family: Georgia, serif;
}

.auth-quote {
    font-family: 'Playfair Display', Georgia, serif;
    font-style: italic;
    font-size: 1.4rem;
    line-height: 1.55;
    color: rgba(255, 255, 255, 0.92);
    border: none;
    padding: 0;
    margin: 12px 0;
}

.auth-quote-author {
    font-size: .875rem;
    opacity: .7;
    margin-top: 8px;
}

/* Footer */
.auth-left-footer {
    margin-top: auto;
}

.auth-gold-line {
    width: 48px;
    height: 3px;
    background: #D4A017;
    border-radius: 2px;
    margin-bottom: 14px;
}

.auth-left-footer p {
    font-size: .78rem;
    opacity: .6;
    line-height: 1.6;
}

/* RIGHT Panel */
.auth-right {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 40px;
    overflow-y: auto;
}

.auth-form-wrap {
    width: 100%;
    max-width: 400px;
}

/* Headings */
.auth-title {
    font-size: 1.75rem;
    font-weight: 700;
    color: #1A1A1A;
    margin-bottom: 8px;
}

.auth-subtitle {
    font-size: .9rem;
    color: #6B7280;
    line-height: 1.5;
    margin-bottom: 28px;
}

/* Label row with forgot password */
.auth-label-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 6px;
}

.auth-label-row .form-label {
    margin-bottom: 0;
}

.auth-forgot {
    font-size: .8rem;
    font-weight: 600;
    color: #7D1316;
}

.auth-forgot:hover {
    text-decoration: underline;
}

/* Remember checkbox */
.auth-remember {
    margin-top: 4px;
}

.auth-checkbox-label {
    display: flex;
    align-items: center;
    gap: 10px;
    cursor: pointer;
    font-size: .875rem;
    color: #374151;
    user-select: none;
}

.auth-checkbox-label input[type="checkbox"] {
    position: absolute;
    opacity: 0;
    width: 0;
    height: 0;
}

.auth-checkbox-custom {
    width: 18px;
    height: 18px;
    border: 1.5px solid #D1D5DB;
    border-radius: 4px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all .2s ease;
}

.auth-checkbox-label input:checked~.auth-checkbox-custom {
    background: #7D1316;
    border-color: #7D1316;
}

.auth-checkbox-label input:checked~.auth-checkbox-custom::after {
    content: '';
    width: 5px;
    height: 9px;
    border: 2px solid #fff;
    border-top: none;
    border-left: none;
    transform: rotate(45deg) translateY(-1px);
    display: block;
}

/* Divider */
.auth-divider {
    text-align: center;
    margin: 24px 0 12px;
    color: #6B7280;
    font-size: .875rem;
}

/* Footer links */
.auth-footer-links {
    display: flex;
    justify-content: center;
    gap: 20px;
    margin-top: 24px;
}

.auth-footer-links a {
    font-size: .78rem;
    color: #9CA3AF;
}

.auth-footer-links a:hover {
    color: #7D1316;
}

/*  Sign-In button (gold) override  */
#loginBtn {
    background: #D4A017;
    color: #1A1A1A;
    font-size: 1rem;
    padding: 14px 22px;
    border-radius: 8px;
    font-weight: 700;
    width: 100%;
    margin-top: 8px;
}

#loginBtn:hover {
    background: #b8890e;
}

#loginBtn:disabled {
    opacity: .7;
    cursor: not-allowed;
}

/* Loading spinner on button */
.btn-loading {
    position: relative;
    pointer-events: none;
}

.btn-loading::after {
    content: '';
    position: absolute;
    right: 18px;
    top: 50%;
    transform: translateY(-50%);
    width: 16px;
    height: 16px;
    border: 2px solid rgba(0, 0, 0, 0.2);
    border-top-color: #1A1A1A;
    border-radius: 50%;
    animation: spin .7s linear infinite;
}

@keyframes spin {
    to {
        transform: translateY(-50%) rotate(360deg);
    }
}


/* Responsive */
@media (max-width: 768px) {
    .auth-split {
        flex-direction: column;
    }

    .auth-left {
        width: 100%;
        min-height: 280px;
        padding: 28px 24px;
    }

    .auth-right {
        padding: 28px 20px;
    }

    .auth-quote {
        font-size: 1.1rem;
    }
}

css\\dashboard.css:
/*  Dashboard Specific Styles  */

.dashboard-layout {
  display: flex;
  min-height: 100vh;
  background: #F8F9FA;
}

/*  Sidebar */
.sidebar {
  width: 260px;
  background: var(--color-primary);
  color: #fff;
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  position: sticky;
  top: 0;
  height: 100vh;
}

.sidebar-header {
  padding: 32px 24px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.sidebar-logo {
  width: 44px;
  height: 44px;
  background: rgba(255, 255, 255, 0.15);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  flex-shrink: 0;
}

.sidebar-logo img {
  width: 36px;
  height: 36px;
  object-fit: contain;
}

.sidebar-title {
  font-weight: 700;
  font-size: 0.85rem;
  letter-spacing: 0.05em;
  line-height: 1.2;
}

.sidebar-nav {
  flex: 1;
  padding: 0 16px;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 20px;
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.95rem;
  font-weight: 500;
  border-radius: var(--radius);
  transition: var(--transition);
  margin-bottom: 4px;
  position: relative;
}

.nav-item:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  text-decoration: none;
}

.nav-item.active {
  background: rgba(255, 255, 255, 0.15);
  color: #fff;
  box-shadow: inset 4px 0 0 var(--color-accent);
}

.nav-badge {
  background: var(--color-accent);
  color: #1A1A1A;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 10px;
  margin-left: auto;
}

.nav-badge-glow {
  box-shadow: 0 0 0 3px rgba(212, 160, 23, 0.22), 0 0 14px rgba(212, 160, 23, 0.55);
}

.sidebar-footer {
  padding: 24px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  display: flex;
  align-items: center;
  gap: 12px;
}

.user-info .name {
  display: block;
  font-weight: 600;
  font-size: 0.9rem;
}

.user-info .id {
  font-size: 0.75rem;
  color: rgba(255, 255, 255, 0.6);
}

.logout-btn {
  margin-left: auto;
  color: rgba(255, 255, 255, 0.6);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.logout-btn:hover {
  color: #fff;
  text-decoration: none;
}

/*  Main Content */
.main-wrapper {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow-x: hidden;
}

.top-bar {
  height: 64px;
  background: #fff;
  padding: 0 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--color-border);
}

.top-bar-title {
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--color-primary);
}

.top-bar-actions {
  display: flex;
  align-items: center;
  gap: 20px;
}

.content-body {
  padding: 32px;
  overflow-y: auto;
  min-width: 0;
}

.section-heading-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
}

.section-heading-row h3 {
  font-size: 1.1rem;
  font-weight: 700;
}

/*  Welcome Banner  */
.welcome-banner {
  background: linear-gradient(135deg, #7D1316 0%, #4a0b0d 100%);
  border-radius: var(--radius-lg);
  padding: 32px;
  color: #fff;
  margin-bottom: 32px;
  box-shadow: var(--shadow-md);
}

.welcome-banner h2 {
  font-size: 1.8rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.welcome-banner p {
  opacity: 0.9;
  font-size: 1rem;
}

.welcome-banner b {
  color: var(--color-accent);
}

/*  Tracker  */
.tracker-card {
  padding: 24px;
  background: #fff;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  margin-bottom: 32px;
}

.tracker-title {
  font-weight: 700;
  margin-bottom: 24px;
}

.workflow-container {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  position: relative;
  padding: 0 20px;
}

.workflow-line {
  position: absolute;
  top: 17px;
  left: 50px;
  right: 50px;
  height: 4px;
  background: #E5E7EB;
  z-index: 1;
}

.workflow-line-progress {
  height: 100%;
  background: var(--color-success);
  width: 50%; /* Example progress */
}

.workflow-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  z-index: 2;
  flex: 1;
  text-align: center;
}

.workflow-dot {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: #fff;
  border: 4px solid #E5E7EB;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.8rem;
  color: var(--color-muted);
}

.workflow-item.completed .workflow-dot {
  background: var(--color-success);
  border-color: var(--color-success);
  color: #fff;
}

.workflow-item.active .workflow-dot {
  border-color: var(--color-warning);
  color: var(--color-warning);
  background: #fff;
}

.workflow-label {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--color-muted);
}

.workflow-item.completed .workflow-label,
.workflow-item.active .workflow-label {
  color: var(--color-text);
}

.workflow-status {
  font-size: 0.75rem;
  color: var(--color-muted);
}

.workflow-item.active .workflow-status {
  color: var(--color-warning);
}

.supervisor-alert {
  margin-bottom: 24px;
}

.project-details-card {
  margin-bottom: 24px;
  padding: 24px;
  background: #fff;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}

.project-details-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 24px;
  align-items: start;
}

.project-edit-form textarea.form-input {
  resize: vertical;
  min-height: 132px;
}

.project-side-panel {
  display: grid;
  gap: 16px;
}

.supervisor-card,
.progress-card,
.supervisor-request-card {
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 18px;
  background: #F9FAFB;
}

.supervisor-card h3,
.progress-card h3,
.supervisor-request-card h3 {
  font-size: 1rem;
  margin-bottom: 14px;
}

.supervisor-request-card textarea.form-input {
  resize: vertical;
  min-height: 96px;
}

.detail-label {
  color: var(--color-muted);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.detail-value {
  display: block;
  color: var(--color-text);
  font-size: 0.95rem;
  font-weight: 600;
  margin-bottom: 12px;
  overflow-wrap: anywhere;
}

.detail-link {
  color: var(--color-primary);
}

.milestone-timeline {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(260px, 320px);
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 8px;
}

.timeline-card {
  border: 1px solid var(--color-border);
  border-top: 4px solid var(--color-border);
  border-radius: var(--radius);
  padding: 16px;
  background: #F8FAFC;
  min-height: 210px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.timeline-card.is-complete {
  border-color: #A7F3D0;
  border-top-color: var(--color-success);
  background: #ECFDF5;
}
.timeline-card.is-active { border-top-color: var(--color-warning); }
.timeline-card.is-revision { border-top-color: var(--color-error); }
.timeline-card.is-overdue { border-top-color: var(--color-warning); }
.timeline-card.is-locked {
  border-top-color: #94A3B8;
  background: #F8FAFC;
}

.locked-note {
  margin-top: 10px;
  padding: 8px 10px;
  border-radius: var(--radius);
  background: #F1F5F9;
  color: #475569;
  font-size: 0.78rem;
  font-weight: 700;
}

.status-approved {
  background: #ECFDF5;
  border-color: #A7F3D0 !important;
}

.status-pending {
  background: #FFFBEB;
  border-color: #FDE68A !important;
}

.status-approved .status-pill {
  background: #D1FAE5;
  color: #065F46;
}

.status-pending .status-pill {
  background: #FEF3C7;
  color: #92400E;
}

.timeline-card.is-complete .timeline-status {
  color: #065F46;
  background: #D1FAE5;
  border-radius: 999px;
  padding: 3px 8px;
}

.timeline-card-header,
.timeline-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.timeline-type,
.timeline-status {
  font-size: 0.72rem;
  font-weight: 800;
  text-transform: uppercase;
  color: var(--color-muted);
}

.timeline-card h4 {
  margin: 12px 0 8px;
  font-size: 1rem;
}

.timeline-card p {
  color: var(--color-muted);
  font-size: 0.85rem;
}

.timeline-meta {
  color: var(--color-muted);
  font-size: 0.75rem;
  margin-top: 14px;
}

.empty-state {
  width: 100%;
  min-height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-muted);
  border: 1px dashed var(--color-border);
  border-radius: var(--radius);
  background: #F9FAFB;
}

/* Grid Layout */
.dashboard-grid {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 32px;
}

/* Carousel Navigation Buttons */
.carousel-nav {
  position: absolute;
  top: 12px;
  right: 24px;
  display: flex;
  gap: 8px;
  z-index: 10;
}

.carousel-btn {
  width: 32px;
  height: 32px;
  border: 1px solid var(--color-border);
  background: #fff;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition);
  color: var(--color-text);
}

.carousel-btn:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
  background: #F9FAFB;
}

.carousel-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.carousel-btn:disabled:hover {
  border-color: var(--color-border);
  color: var(--color-text);
  background: #fff;
}

/*  Milestone Progress  */
.milestones-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.milestones-header h3 {
  font-weight: 700;
}

.milestone-cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-bottom: 24px;
}

.milestone-cards.collapsed > *:nth-child(n+5) {
  display: none !important;
}

.milestone-mini-card {
  background: #F9FAFB;
  padding: 16px;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  gap: 16px;
  border: 1px solid var(--color-border);
}

.milestone-info .title {
  display: block;
  font-weight: 700;
  font-size: 0.9rem;
}

.milestone-info .status {
  font-size: 0.75rem;
  color: var(--color-success);
  font-weight: 600;
}

/*  Feedback  */
.feedback-box {
  background: #EFF6FF;
  border-left: 4px solid var(--color-info);
  padding: 16px 20px;
  border-radius: var(--radius);
  display: flex;
  gap: 14px;
}

.feedback-content strong {
  display: block;
  margin-bottom: 4px;
}

.feedback-content p {
  font-size: 0.85rem;
  color: #1E40AF;
}

/*  Pending Actions  */
.action-card {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow);
}

.action-card h3 {
  font-weight: 700;
  margin-bottom: 20px;
}

.action-item {
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 16px;
  margin-bottom: 16px;
  position: relative;
}

.action-item.urgent {
  background: #FFF5F5;
  border-color: #FED7D7;
}

.action-tag {
  position: absolute;
  top: 12px;
  right: 12px;
  font-size: 0.65rem;
  font-weight: 800;
  padding: 2px 6px;
  border-radius: 4px;
}

.action-tag.urgent {
  background: #FEB2B2;
  color: #9B2C2C;
}

.action-content .title {
  display: block;
  font-weight: 700;
  font-size: 0.9rem;
  margin-bottom: 4px;
  padding-right: 60px;
}

.action-content .desc {
  font-size: 0.8rem;
  color: var(--color-muted);
  margin-bottom: 12px;
  display: block;
}

/*  Recent Files  */
.recent-files-card {
  margin-top: 32px;
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow);
}

.file-row {
  display: flex;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px solid var(--color-border);
}

.file-row:last-child {
  border-bottom: none;
}

.file-icon {
  width: 32px;
  height: 32px;
  background: #F3F4F6;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: 16px;
  color: var(--color-primary);
}

.file-details {
  flex: 1;
  min-width: 0;
}

.file-details span {
  display: block;
  overflow-wrap: anywhere;
}

.file-download-btn {
  padding: 6px;
  border-width: 1px;
}

.notification-row {
  padding: 10px 0;
  border-bottom: 1px solid #f1f1f1;
}

.notification-row strong,
.notification-row span {
  display: block;
  font-size: 0.85rem;
}

.notification-row span {
  color: var(--color-muted);
  margin-top: 2px;
}

.profile-edit-card {
  max-width: 920px;
}

.profile-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.profile-divider {
  border: none;
  border-top: 1px solid var(--color-border);
  margin: 10px 0 24px;
}

.profile-actions {
  display: flex;
  justify-content: flex-end;
}

/* Responsive Design */
@media (max-width: 1200px) {
  .dashboard-grid {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .milestone-timeline {
    grid-auto-columns: minmax(240px, 1fr);
  }
}

@media (max-width: 980px) {
  .project-details-grid,
  .profile-form-grid {
    grid-template-columns: 1fr;
  }

  .milestone-timeline {
    grid-auto-columns: minmax(220px, 1fr);
  }

  .carousel-nav {
    right: 16px;
  }
}

@media (max-width: 768px) {
  .content-body {
    padding: 20px;
  }

  .project-details-card {
    padding: 16px;
  }

  .tracker-card {
    padding: 16px;
    margin-bottom: 16px;
  }

  .dashboard-grid {
    gap: 16px;
  }

  .milestone-timeline {
    grid-auto-columns: minmax(200px, 1fr);
  }

  .timeline-card {
    min-height: 180px;
  }

  .timeline-card h4 {
    font-size: 0.9rem;
  }

  .timeline-card p {
    font-size: 0.75rem;
  }

  .carousel-btn {
    width: 28px;
    height: 28px;
    font-size: 0.75rem;
  }
}

css\\style.css:
/* 
   Brand: --color-primary #7D1316 (CUEA Maroon)
          --color-accent  #D4A017 (Gold)
 */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Playfair+Display:ital,wght@1,600&display=swap');

/*  CSS Variables  */
:root {
  --color-primary: #7D1316;
  --color-primary-d: #5c0e10;
  --color-accent: #D4A017;
  --color-accent-h: #b8890e;
  --color-bg: #F7F7F7;
  --color-card: #FFFFFF;
  --color-text: #1A1A1A;
  --color-muted: #6B7280;
  --color-border: #E5E7EB;
  --color-error: #DC2626;
  --color-success: #059669;
  --radius: 8px;
  --radius-lg: 12px;
  --shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  --shadow-md: 0 4px 16px rgba(0, 0, 0, 0.12);
  --transition: all 0.2s ease;
  --color-warning: #F59E0B;
  --color-info: #3B82F6;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.05);
}

/*  Reset  */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100vh;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: var(--color-primary);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/*  Dashboard Layout  */
.layout {
  display: flex;
  min-height: 100vh;
}

.sidebar {
  width: 240px;
  background: var(--color-primary);
  color: #fff;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
}

.main-content {
  flex: 1;
  padding: 24px;
  background: var(--color-bg);
  overflow-y: auto;
}

/*  Sidebar  */
.sidebar-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 20px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.sidebar-logo img {
  width: 36px;
  height: 36px;
  border-radius: 6px;
  object-fit: contain;
}

.sidebar-logo span {
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  opacity: .9;
  line-height: 1.3;
}

.sidebar nav {
  padding: 12px 0;
  flex: 1;
}

.sidebar nav a {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 18px;
  color: rgba(255, 255, 255, 0.85);
  font-size: .875rem;
  font-weight: 500;
  transition: var(--transition);
  border-left: 3px solid transparent;
}

.sidebar nav a:hover,
.sidebar nav a.active {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  border-left-color: var(--color-accent);
  text-decoration: none;
}

.sidebar-bottom {
  padding: 16px 18px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

/*  Cards  */
.card {
  background: var(--color-card);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  padding: 20px;
  margin-bottom: 16px;
}

/*  Status Badges  */
.badge {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 12px;
  font-size: .78rem;
  font-weight: 600;
}

.badge-approved {
  background: #D1FAE5;
  color: #065F46;
}

.badge-pending {
  background: #FEF3C7;
  color: #92400E;
}

.badge-rejected {
  background: #FEE2E2;
  color: #991B1B;
}

.badge-revision {
  background: #DBEAFE;
  color: #1E40AF;
}

.badge-draft {
  background: #F3F4F6;
  color: #374151;
}

.badge-submitted {
  background: #EDE9FE;
  color: #5B21B6;
}

/*  Buttons  */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 11px 22px;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  font-size: .9rem;
  font-weight: 600;
  font-family: inherit;
  transition: var(--transition);
  text-decoration: none;
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-primary);
  color: #fff;
}

.btn-primary:hover {
  background: var(--color-primary-d);
  color: #fff;
  text-decoration: none;
}

.btn-accent {
  background: var(--color-accent);
  color: #1A1A1A;
}

.btn-accent:hover {
  background: var(--color-accent-h);
  text-decoration: none;
}

.btn-outline {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}

.btn-outline:hover {
  background: var(--color-primary);
  color: #fff;
  text-decoration: none;
}

.btn-outline-white {
  background: transparent;
  color: #fff;
  border: 2px solid rgba(255, 255, 255, 0.5);
}

.btn-outline-white:hover {
  background: rgba(255, 255, 255, 0.1);
  text-decoration: none;
}

.btn-full {
  width: 100%;
}

.btn:disabled {
  opacity: .6;
  cursor: not-allowed;
}

/*  Form Elements  */
.form-group {
  margin-bottom: 18px;
}

.form-label {
  display: block;
  font-size: .85rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 6px;
}

.form-input {
  width: 100%;
  padding: 11px 14px;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius);
  font-size: .9rem;
  font-family: inherit;
  color: var(--color-text);
  background: #fff;
  transition: var(--transition);
  outline: none;
}

.form-input::placeholder {
  color: #9CA3AF;
}

.form-input:focus {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(125, 19, 22, .1);
}

.input-icon-wrap {
  position: relative;
}

.input-icon-wrap .form-input {
  padding-left: 42px;
}

.input-icon-wrap .input-icon {
  position: absolute;
  left: 13px;
  top: 50%;
  transform: translateY(-50%);
  color: #9CA3AF;
  font-size: 1rem;
  pointer-events: none;
}

.input-icon-wrap .input-icon-right {
  position: absolute;
  right: 13px;
  top: 50%;
  transform: translateY(-50%);
  color: #9CA3AF;
  cursor: pointer;
  font-size: 1rem;
  background: none;
  border: none;
  padding: 0;
}

.input-icon-wrap .input-icon-right:hover {
  color: var(--color-text);
}

.form-error {
  color: var(--color-error);
  font-size: .8rem;
  margin-top: 5px;
}

.form-hint {
  color: var(--color-muted);
  font-size: .8rem;
  margin-top: 5px;
}

/*  Alert / Message  */
.alert {
  padding: 12px 16px;
  border-radius: var(--radius);
  font-size: .875rem;
  margin-bottom: 16px;
  display: none;
}

.alert.show {
  display: block;
}

.alert-error {
  background: #FEF2F2;
  color: #991B1B;
  border: 1px solid #FCA5A5;
}

.alert-success {
  background: #F0FDF4;
  color: #166534;
  border: 1px solid #86EFAC;
}

.alert-info {
  background: #EFF6FF;
  color: #1E40AF;
  border: 1px solid #93C5FD;
}

/*  Workflow Tracker  */
.workflow-tracker {
  margin-bottom: 24px;
}

.workflow-steps {
  display: flex;
  align-items: center;
}

.workflow-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1;
  position: relative;
}

.workflow-step:not(:last-child)::after {
  content: '';
  position: absolute;
  top: 17px;
  left: calc(50% + 17px);
  width: calc(100% - 34px);
  height: 2px;
  background: var(--color-border);
}

.workflow-step.completed::after {
  background: var(--color-primary);
}

.step-dot {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .8rem;
  font-weight: 700;
  z-index: 1;
  border: 2px solid var(--color-border);
  background: #fff;
  color: var(--color-muted);
}

.workflow-step.completed .step-dot {
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: #fff;
}

.workflow-step.active .step-dot {
  border-color: var(--color-primary);
  color: var(--color-primary);
  box-shadow: 0 0 0 4px rgba(125, 19, 22, .15);
}

.step-label {
  font-size: .75rem;
  margin-top: 8px;
  text-align: center;
  color: var(--color-muted);
  font-weight: 500;
}

.workflow-step.active .step-label,
.workflow-step.completed .step-label {
  color: var(--color-text);
}

/*  Toast Notifications  */
.toast {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 9999;
  padding: 12px 18px;
  border-radius: var(--radius);
  color: #fff;
  font-size: .875rem;
  font-weight: 500;
  box-shadow: var(--shadow-md);
  animation: slideInToast .3s ease;
  max-width: 320px;
}

.toast-reminder {
  background: #1E40AF;
}

.toast-comment {
  background: var(--color-primary);
}

.toast-status_change {
  background: var(--color-accent);
  color: #1A1A1A;
}

.toast-assignment {
  background: #065F46;
}

.toast-general {
  background: #374151;
}

@keyframes slideInToast {
  from {
    transform: translateX(120%);
    opacity: 0;
  }

  to {
    transform: translateX(0);
    opacity: 1;
  }
}

/*  Tables  */
.table-wrapper {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: .875rem;
}

thead th {
  background: #F9FAFB;
  padding: 10px 14px;
  text-align: left;
  font-weight: 600;
  font-size: .78rem;
  text-transform: uppercase;
  letter-spacing: .05em;
  color: var(--color-muted);
  border-bottom: 1px solid var(--color-border);
}

tbody td {
  padding: 12px 14px;
  border-bottom: 1px solid var(--color-border);
  vertical-align: middle;
}

tbody tr:last-child td {
  border-bottom: none;
}

tbody tr:hover {
  background: #FAFAFA;
}

/*  Page Header  */
.page-header {
  margin-bottom: 24px;
}

.page-header h1 {
  font-size: 1.5rem;
  font-weight: 700;
}

.page-header p {
  color: var(--color-muted);
  margin-top: 4px;
}

/*  Avatars  */
.avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
  background: var(--color-border);
  flex-shrink: 0;
}

.avatar-lg {
  width: 48px;
  height: 48px;
}

.avatar-sm {
  width: 32px;
  height: 32px;
}

/*  Progress Indicators  */
.progress-bar-container {
  width: 100%;
  height: 8px;
  background: var(--color-border);
  border-radius: 4px;
  overflow: hidden;
  position: relative;
}

.progress-bar-fill {
  height: 100%;
  background: var(--color-primary);
  transition: width 0.5s ease-out;
}

.progress-bar-fill.success {
  background: var(--color-success);
}

.progress-bar-fill.warning {
  background: var(--color-warning);
}

.progress-bar-fill.error {
  background: var(--color-error);
}

.circular-progress {
  position: relative;
  width: 60px;
  height: 60px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.circular-progress::before {
  content: "";
  position: absolute;
  height: 84%;
  width: 84%;
  background-color: #fff;
  border-radius: 50%;
}

.progress-value {
  position: relative;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--color-text);
}

/*  Tags  */
.tag {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.7rem;
  font-weight: 600;
  background: #F3F4F6;
  color: #374151;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.tag-blue {
  background: #DBEAFE;
  color: #1E40AF;
}

.tag-purple {
  background: #EDE9FE;
  color: #5B21B6;
}

.tag-green {
  background: #D1FAE5;
  color: #065F46;
}

/*  Typography Helpers  */
.text-xs {
  font-size: 0.75rem;
}

.text-sm {
  font-size: 0.875rem;
}

.font-bold {
  font-weight: 700;
}

.text-muted {
  color: var(--color-muted);
}

/*  Responsive  */
@media (max-width: 768px) {
  .layout {
    flex-direction: column;
  }

  .sidebar {
    width: 100%;
  }

  .sidebar nav {
    display: flex;
    overflow-x: auto;
    padding: 8px 0;
  }

  .sidebar nav a {
    flex-direction: column;
    gap: 4px;
    padding: 8px 14px;
    border-left: none;
    border-bottom: 3px solid transparent;
    font-size: .75rem;
  }

  .sidebar nav a.active {
    border-left-color: transparent;
    border-bottom-color: var(--color-accent);
  }

  .main-content {
    padding: 14px;
  }

  .card {
    padding: 14px;
  }
}

@media (min-width: 768px) and (max-width: 1024px) {
  .sidebar {
    width: 200px;
  }
}

css\\supervisor.css:
/*  Supervisor Selection Specific Styles  */

.top-nav {
  height: 64px;
  background: #fff;
  border-bottom: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 40px;
  position: sticky;
  top: 0;
  z-index: 100;
}

.nav-brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nav-brand img {
  height: 32px;
  width: auto;
  object-fit: contain;
}

.nav-brand-text {
  display: flex;
  flex-direction: column;
}

.nav-brand-name {
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--color-primary);
}

.nav-brand-sub {
  font-size: 0.7rem;
  color: var(--color-accent);
  font-weight: 600;
}

.nav-links {
  display: flex;
  gap: 32px;
  height: 100%;
}

.nav-links a {
  display: flex;
  align-items: center;
  color: var(--color-muted);
  font-weight: 500;
  font-size: 0.9rem;
  border-bottom: 3px solid transparent;
  transition: var(--transition);
}

.nav-links a:hover, .nav-links a.active {
  color: var(--color-text);
  border-bottom-color: var(--color-accent);
  text-decoration: none;
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 20px;
}

.nav-icon-btn {
  background: none;
  border: none;
  color: var(--color-muted);
  cursor: pointer;
  position: relative;
}

.nav-icon-btn .badge-dot {
  position: absolute;
  top: -2px;
  right: -2px;
  width: 8px;
  height: 8px;
  background: var(--color-error);
  border-radius: 50%;
  border: 2px solid #fff;
}

.user-profile-summary {
  display: flex;
  align-items: center;
  gap: 10px;
}

.user-profile-summary span {
  font-weight: 600;
  font-size: 0.9rem;
}

/*  Content Layout */
.selection-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 32px 40px;
}

.breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.85rem;
  color: var(--color-muted);
  margin-bottom: 24px;
}

.breadcrumb a {
  color: var(--color-muted);
}

.breadcrumb-separator {
  color: var(--color-border);
}

.breadcrumb .active {
  color: var(--color-accent);
  font-weight: 600;
}

.selection-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 32px;
}

/*  Filters  */
.filter-bar {
  display: flex;
  gap: 16px;
  margin-bottom: 24px;
  background: #fff;
  padding: 16px;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}

.filter-search {
  flex: 1;
}

.filter-select {
  width: 200px;
}

/*  Faculty Table  */
.faculty-card {
  background: #fff;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

.faculty-table th {
  background: #F9FAFB;
  text-transform: uppercase;
  font-size: 0.75rem;
  letter-spacing: 0.05em;
  color: var(--color-muted);
  padding: 12px 20px;
  border-bottom: 1px solid var(--color-border);
}

.faculty-table td {
  padding: 16px 20px;
  vertical-align: middle;
}

.faculty-info {
  display: flex;
  align-items: center;
  gap: 12px;
}

.faculty-details .name {
  display: block;
  font-weight: 600;
  color: var(--color-text);
}

.faculty-details .dept {
  font-size: 0.75rem;
  color: var(--color-muted);
}

.interest-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.availability-wrap {
  width: 140px;
}

.availability-text {
  font-size: 0.75rem;
  font-weight: 600;
  margin-bottom: 4px;
  display: flex;
  justify-content: space-between;
}

.action-btn {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 1px solid var(--color-border);
  background: none;
  color: var(--color-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
}

.action-btn:hover:not(:disabled) {
  border-color: var(--color-accent);
  color: var(--color-accent);
  background: rgba(212, 160, 23, 0.05);
}

.action-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

/*  Preferences Sidebar  */
.preferences-card {
  background: #fff;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  padding: 24px;
  position: sticky;
  top: 96px;
  border-top: 4px solid var(--color-primary);
}

.preferences-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  margin-bottom: 8px;
}

.preferences-subtitle {
  font-size: 0.8rem;
  color: var(--color-muted);
  margin-bottom: 20px;
}

.preference-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.preference-slot {
  border: 1px dashed var(--color-border);
  border-radius: var(--radius);
  padding: 12px;
  min-height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #F9FAFB;
  font-size: 0.85rem;
  color: var(--color-muted);
  transition: var(--transition);
}

.preference-slot.filled {
  border-style: solid;
  background: #fff;
  border-color: var(--color-border);
  justify-content: space-between;
}

.slot-rank {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: #FEF3C7;
  color: #92400E;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  margin-right: 12px;
}

.slot-content {
  flex: 1;
}

.slot-name {
  font-weight: 600;
  font-size: 0.85rem;
  display: block;
}

.slot-dept {
  font-size: 0.7rem;
  color: var(--color-muted);
}

.slot-actions {
  display: flex;
  gap: 8px;
  color: var(--color-muted);
}

.slot-remove {
  cursor: pointer;
  padding: 4px;
}

.slot-remove:hover {
  color: var(--color-error);
}

.confirm-check {
  margin-bottom: 20px;
}

.checkbox-label {
  display: flex;
  gap: 10px;
  font-size: 0.8rem;
  color: var(--color-muted);
  cursor: pointer;
}

.checkbox-label input {
  margin-top: 2px;
}

js\\auth.js:
/**
 * CUEA FYPM – Authentication JS
 * Handles: Login form, Register multi-step form
 */

'use strict';

/* ─────────────────────────────────────────────────────────
   UTILITIES
───────────────────────────────────────────────────────── */
function showAlert(id, type, message) {
  const el = document.getElementById(id);
  if (!el) return;
  el.className = `alert alert-${type} show`;
  el.textContent = message;
  el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function hideAlert(id) {
  const el = document.getElementById(id);
  if (el) { el.className = 'alert'; el.textContent = ''; }
}

function setLoading(btnId, loading) {
  const btn = document.getElementById(btnId);
  if (!btn) return;
  btn.disabled = loading;
  if (loading) btn.classList.add('btn-loading');
  else btn.classList.remove('btn-loading');
}

/* ─────────────────────────────────────────────────────────
   LOGIN PAGE
───────────────────────────────────────────────────────── */
(function initLogin() {
  const form = document.getElementById('loginForm');
  if (!form) return;  // Not on login page

  const reasonMessages = {
    session_expired: 'Your session expired. Please log in again.',
    session_invalid: 'Your previous session is no longer valid. Please log in again.',
    role_changed: 'You are signed in as a different role in this browser. Please log in again to continue.',
    account_switched: 'This tab was opened for a different account. Please log in again to continue safely.',
    logged_out: 'You have been signed out successfully.'
  };
  const reason = new URLSearchParams(window.location.search).get('reason');
  if (reason && reasonMessages[reason]) {
    showAlert('loginAlert', reason === 'logged_out' ? 'success' : 'info', reasonMessages[reason]);
  }

  // ── Password show/hide toggle ──────────────────────────
  const togglePwd  = document.getElementById('togglePwd');
  const pwdInput   = document.getElementById('loginPassword');
  const eyeIcon    = document.getElementById('eyeIcon');
  const eyeOffIcon = document.getElementById('eyeOffIcon');

  if (togglePwd) {
    togglePwd.addEventListener('click', () => {
      const isHidden = pwdInput.type === 'password';
      pwdInput.type  = isHidden ? 'text' : 'password';
      eyeIcon.style.display    = isHidden ? 'none'  : '';
      eyeOffIcon.style.display = isHidden ? ''      : 'none';
      togglePwd.setAttribute('aria-label', isHidden ? 'Hide password' : 'Show password');
    });
  }

  // ── Login submit ──────────────────────────────────────
  form.addEventListener('submit', handleLogin);

  async function handleLogin(e) {
    e.preventDefault();
    hideAlert('loginAlert');

    const universityId = document.getElementById('universityId').value.trim();
    const password     = document.getElementById('loginPassword').value;
    const remember     = document.getElementById('rememberMe')?.checked ?? false;

    if (!universityId) { showAlert('loginAlert', 'error', 'Please enter your University ID.'); return; }
    if (!password)     { showAlert('loginAlert', 'error', 'Please enter your password.'); return; }

    setLoading('loginBtn', true);

    try {
      const res  = await fetch('php/api/auth.php?action=login', {
        method:  'POST',
        headers: { 'Content-Type': 'application/json', 'X-Requested-With': 'XMLHttpRequest' },
        body:    JSON.stringify({ university_id: universityId, password, remember })
      });
      const data = await res.json();

      if (res.ok && data.status === 200) {
        sessionStorage.setItem('cuea_session_user_id', String(data.data.user_id));
        sessionStorage.setItem('cuea_session_role', data.data.role);

        // Role-based redirect
        let redirectUrl = 'dashboard.php';
        if (data.data.role === 'student') {
          redirectUrl = data.data.has_supervisor
            ? 'dashboard.php'
            : (data.data.has_pending_supervisor_preferences ? 'pending-supervisor.php' : 'supervisor-selection.html');
        } else if (data.data.role === 'supervisor') {
          redirectUrl = 'supervisor-dashboard.php';
        } else if (data.data.role === 'coordinator') {
          redirectUrl = 'coordinator.php';
        }

        showAlert('loginAlert', 'success', `Welcome back, ${data.data.full_name}! Redirecting…`);
        setTimeout(() => {
          window.location.href = redirectUrl;
        }, 800);
      } else {
        showAlert('loginAlert', 'error', data.message || 'Login failed. Please try again.');
        setLoading('loginBtn', false);
      }
    } catch (err) {
      showAlert('loginAlert', 'error', 'Network error. Please check your connection and try again.');
      setLoading('loginBtn', false);
    }
  }

  // ── Clear error on input ──────────────────────────────
  ['universityId', 'loginPassword'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('input', () => hideAlert('loginAlert'));
  });
})();


/* ─────────────────────────────────────────────────────────
   END OF AUTH JS (Registration removed)
───────────────────────────────────────────────────────── */

